import { useState } from "react";
import "./App.css";

function App() {
  const [form, setForm] = useState({
    type: "PAYMENT",
    amount: "",
    oldbalanceOrg: "",
    newbalanceOrig: "",
    oldbalanceDest: "",
    newbalanceDest: "",
    threshold: 0.5
  });

  const [result, setResult] = useState(null);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handlePredict = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/predict", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...form,
          amount: parseFloat(form.amount),
          oldbalanceOrg: parseFloat(form.oldbalanceOrg),
          newbalanceOrig: parseFloat(form.newbalanceOrig),
          oldbalanceDest: parseFloat(form.oldbalanceDest),
          newbalanceDest: parseFloat(form.newbalanceDest),
          threshold: parseFloat(form.threshold)
        })
      });

      if (!res.ok) {
        const err = await res.json();
        console.error("Erreur API :", err);
        return;
      }

      const data = await res.json();
      setResult(data);
    } catch (err) {
      console.error("Erreur fetch :", err);
      alert("Impossible de contacter le backend.");
    }
  };

  return (
    <div className="container">
      <h1>Fraud Detection</h1>

      <div className="form-container">
        <div className="input-group">
          <label>Type</label>
          <select name="type" value={form.type} onChange={handleChange}>
            <option value="PAYMENT">PAYMENT</option>
            <option value="TRANSFER">TRANSFER</option>
            <option value="DEBIT">DEBIT</option>
            <option value="CASH_OUT">CASH_OUT</option>
            <option value="CASH_IN">CASH_IN</option>
          </select>
        </div>

        {["amount","oldbalanceOrg","newbalanceOrig","oldbalanceDest","newbalanceDest","threshold"].map(key => (
          <div className="input-group" key={key}>
            <label>{key}</label>
            <input
              name={key}
              type="number"
              value={form[key]}
              onChange={handleChange}
            />
          </div>
        ))}

        <button className="predict-btn" onClick={handlePredict}>Predict</button>
      </div>

      {result && (
        <div className={`result ${result.label === "Fraud" ? "fraud" : "normal"}`}>
          <h2>Result:</h2>
          <p><strong>Prediction:</strong> {result.label}</p>
          <p><strong>Probability:</strong> {result.probability.toFixed(4)}</p>
        </div>
      )}
    </div>
  );
}

export default App;
